# Ancien questionnaire (codé en dur) -> questionnaire du cahier des charges, section 4.
RENOMMAGES = {"A08": "A11", "B01": "B03", "B02": "B05", "B03": "B06", "B04": "B08", "B05": "B07", "C02": "C04",
              "C03": "C05", "F05": "H04", "H01": "I01", "H02": "I03", "H03": "I04"}


def reprendre(apps, schema_editor):
    EPN = apps.get_model("enquete", "EPN")
    EPN.objects.filter(actif=False).update(etat="dissous")
    Reponse = apps.get_model("enquete", "Reponse")
    for r in Reponse.objects.exclude(donnees={}):
        d = dict(r.donnees)
        nouveau = {RENOMMAGES.get(k, k): v for k, v in d.items()}
        if isinstance(nouveau.get("A05"), int):
            nouveau["A05"] = f"{nouveau['A05']}-01-01"  # année de création -> date de création
        r.donnees = nouveau
        r.save(update_fields=["donnees"])
    PieceJointe = apps.get_model("enquete", "PieceJointe")
    for p in PieceJointe.objects.filter(code__in=list(RENOMMAGES)):
        p.code = RENOMMAGES[p.code]
        p.save(update_fields=["code"])


